/**
 * Logs an admin action to the audit log using background task queue
 * to prevent UI freezing
 * @param userId User ID performing the action
 * @param action Description of the action
 * @param resource Resource being acted upon
 * @param details Additional details
 */
export const logAdminAction = async (user_id: string, action: string, resource: string, details?: any): Promise<boolean> => {
  // Use the background task queue to avoid UI freezing
  return await globalTaskQueue.add(async () => {
    try {
      console.log(`Logging admin action in background: ${action} on ${resource}`);
      
      // Use withRetry to handle potential network issues with automatic retry
      const result = await withRetry(async () => {
        return await supabase
          .from("admin_audit_log")
          .insert({
            user_id,
            action,
            resource,
            details
          });
      }, 3, 300);
      
      if (result.error) {
        console.error("Error logging admin action:", result.error);
        return false;
      }
      
      console.log("Admin action logged successfully");
      return true;
    } catch (error) {
      console.error("Exception logging admin action:", error);
      return false;
    }
  });
};

/**
 * Fetches weekly menus from Supabase
 * @returns Promise resolving to weekly menu data
 */
export const fetchWeeklyMenusFromDb = async () => {
  try {
    console.log("Fetching weekly menus from Supabase...");
    
    // Fetch all weekly menus
    const { data: weeklyMenus, error: menuError } = await supabase
      .from('weekly_menus')
      .select('*')
      .order('date', { ascending: true });
    
    if (menuError) {
      console.error("Error fetching weekly menus:", menuError);
      return null;
    }
    
    if (!weeklyMenus || weeklyMenus.length === 0) {
      console.log("No weekly menus found in database");
      return null;
    }
    
    console.log("Fetched weekly menus:", weeklyMenus);
    return weeklyMenus;
    
  } catch (error) {
    console.error("Exception fetching weekly menus:", error);
    return null;
  }
};

